def mse(y_hat, y)
  y_hat.zip(y).sum { |p, t| (p - t) ** 2 } / y.size.to_f
end

def mse_grad(y_hat, y)
  y_hat.zip(y).map { |p, t| 2 * (p - t) / y.size.to_f }
end
